// url=https://www.figma.com/design/yhUDpqfUinkGXN6zgpJVUQ/UI-Kit?node-id=10420-14358
// source=les-emplois itou/utils/templatetags/nav.py (NAV_ENTRIES, nav() for an employer) + itou/templates/utils/templatetags/nav.html
// component=Navigation
const figma = require('figma')
const instance = figma.selectedInstance

// The menu is generated by {% nav request %}: the active entry comes from the current view
// (NavItem.active_view_names), never from the template. This shows the rendered HTML for an
// employer (SIAE) — the Figma menu is a subset of it.
const page = instance.getEnum('Page', {
  'Accueil': 'home',
  'Demandes reçues': 'employer-job-apps',
  'Non sélectionné': '',
  'Rechercher': 'employers-search',
  'Structure / Fiches de poste': 'employer-jobs',
  'Structure / Fiche de présentation': 'employer-company',
  'Structure / Collaborateurs': 'employer-members',
  'Structure / Annexes financières': 'employer-financial-annexes',
  'Accompagnements / PASS IAE': 'employer-approvals',
  'Accompagnements / Fiches salarié ASP': 'employer-employee-records',
})

const menu = [
  { key: 'home', icon: 'ri-home-line', label: 'Accueil', url: 'dashboard:index' },
  { key: 'employer-job-apps', icon: 'ri-mail-download-line', label: 'Demandes reçues', url: 'apply:list_for_siae' },
  {
    slug: 'demandes-envoyees', icon: 'ri-mail-send-line', label: 'Demandes envoyées',
    items: [
      { key: 'employer-job-apps-sent', label: 'Candidatures vers des emplois', url: 'apply:list_prescriptions' },
      { key: 'employer-orientations', label: 'Orientations vers des services', url: 'insertion_views:orientations_list' },
    ],
  },
  {
    slug: 'accompagnements', icon: 'ri-team-line', label: 'Accompagnements',
    items: [
      { key: 'employer-approvals', label: 'PASS IAE', url: 'approvals:list' },
      { key: 'employer-employee-records', label: 'Fiches salarié ASP', url: 'employee_record_views:list' },
      { key: 'employer-assignments', label: 'Usagers accompagnés', url: 'job_seekers_views:list_organization' },
    ],
  },
  {
    slug: 'structure', icon: 'ri-community-line', label: 'Structure',
    items: [
      { key: 'employer-company', label: 'Fiche de présentation', url: 'companies_views:overview' },
      { key: 'employer-jobs', label: 'Fiches de poste', url: 'companies_views:job_description_list' },
      { key: 'employer-members', label: 'Collaborateurs', url: 'companies_views:members' },
      { key: 'employer-financial-annexes', label: 'Annexes financières', url: 'companies_views:show_financial_annexes' },
    ],
  },
  {
    slug: 'rechercher', icon: 'ri-search-line', label: 'Rechercher',
    items: [
      { key: 'employers-search', label: 'Un emploi inclusif', url: 'search:employers_results' },
      { key: 'prescribers-search', label: 'Un accompagnement', url: 'search:prescribers_results' },
      { key: 'services-search', label: "Un service d'insertion", url: 'search:services_results' },
    ],
  },
]

const renderEntry = (entry) => {
  if (!entry.items) {
    const active = entry.key === page ? ' active' : ''
    return `    <li class="nav-item">
        <a href="{% url '${entry.url}' %}" class="nav-link${active}">
            <i class="${entry.icon} fw-medium" aria-hidden="true"></i>
            <span>${entry.label}</span>
        </a>
    </li>`
  }
  const open = entry.items.some((item) => item.key === page)
  const links = entry.items
    .map((item) => `                <li>
                    <a href="{% url '${item.url}' %}"${item.key === page ? ' class="active"' : ''}>${item.label}</a>
                </li>`)
    .join('\n')
  return `    <li class="nav-item">
        <button class="nav-link has-collapse-caret w-100 text-start${open ? ' active' : ''}"
                type="button"
                data-bs-target="#collapse-nav-${entry.slug}"
                data-bs-toggle="collapse"
                aria-expanded="${open}"
                aria-controls="collapse-nav-${entry.slug}">
            <i class="${entry.icon} fw-medium" aria-hidden="true"></i>
            <span>${entry.label}</span>
        </button>
        <div class="collapse${open ? ' show' : ''}" id="collapse-nav-${entry.slug}">
            <ul>
${links}
            </ul>
        </div>
    </li>`
}

const rendered = menu.map(renderEntry).join('\n')

export default {
  example: figma.html`<nav class="flex-grow-1" role="navigation" aria-label="Navigation principale">
    {% nav request %}
</nav>

{# Rendered by utils/templatetags/nav.html #}
<ul class="nav nav-tabs flex-column mb-3">
${rendered}
</ul>`,
  id: 'side-navigation',
  metadata: { nestable: true },
}
